func (q *Queries) UpdateProductPopularity(ctx context.Context, arg UpdateProductPopularityParams) (AnalyticProductPopularity, error) {
	row := q.db.QueryRow(ctx, updateProductPopularity,
		arg.Score,
		arg.ViewCount,
		arg.PurchaseCount,
		arg.FavoriteCount,
		arg.CartCount,
		arg.ReviewCount,
		arg.DateUpdated,
		arg.ID,
	)
	var i AnalyticProductPopularity
	err := row.Scan(
		&i.ID,
		&i.Score,
		&i.ViewCount,
		&i.PurchaseCount,
		&i.FavoriteCount,
		&i.CartCount,
		&i.ReviewCount,
		&i.DateUpdated,
	)
	return i, err
}
